        const started = !(yield* host.running);
        if (started) {
            yield* host.start;
            // A started container has no timeout of its own yet.
            held = false;
        }
        if (held)
            return { started, held: false };
        // Taken before the call, so requests arriving meanwhile don't set it too.
        held = true;
        held = yield* host.setInactivityTimeout(Duration.toMillis(INACTIVITY)).pipe(Effect.as(true), Effect.catch((error) => Effect.logWarning("electric.hold").pipe(Effect.annotateLogs({ error: String(error) }), Effect.as(false))));
